function seed(bool $completed=true):array{global $r,$s,$staff;$r->run("INSERT INTO extras(name,price,stock_qty,active) VALUES(?,1,48,1)",['Synthetic count race '.rk()]);$x=(int)$r->db->lastInsertId();$r->run("INSERT INTO stay_extra_settings(extra_id,category,tracked,low_stock) VALUES(?,'General',1,0)",[$x]);$id=cmd($staff,'start',['items'=>json_encode([$x]),'purpose'=>'Weekly Stock Count'])['id'];if($completed){finish($id,$x,'46.00');submit($id,$x);}return [$id,$x];}
