[$id,$x]=seed(false);cmd($staff,'begin',v($id,$staff)+['extra_id'=>(string)$x]);$out=race([job($staff,'finish',v($id,$staff)+['extra_id'=>(string)$x,'qty'=>'46.00','confirmed'=>'1']),sale($x)]);if(!$out[0]['ok'])finish($id,$x,'45.00');submit($id,$x);cmd($owner,'approve',ap($id));ra($out[1]['ok']&&stock($x)===($out[0]['ok']?'43.00':'45.00'),'Finish versus sale has one valid ordering without lost stock');
