[$id,$x]=seed();$p=new \Tivoli\Service\PurchaseService($a,$clock);$category=(int)$r->run('SELECT id FROM expense_categories WHERE active=1 LIMIT 1')->fetchColumn();$pr=$p->execute($staff,'request',['type'=>'stock','category_id'=>(string)$category,'title'=>'Synthetic count race delivery','supplier'=>'Synthetic vendor','purpose'=>'Sample stock','estimate'=>'6.00','method'=>'momo','extra_id'=>(string)$x,'qty'=>'6.00'],rk())['id'];
