ra($out[1]['ok']&&stock($x)==='52.00'&&(int)$r->run('SELECT COUNT(*) FROM expenses WHERE reference_no=?',['PURCHASE-'.$pr])->fetchColumn()===1,'Purchase receipt versus approval retains delivery cost and quantity once');
